def page(n,body,w,h):
  html=f'<html><head><meta charset="utf-8"><style>{CSS}</style></head><body><div class="top"><div><b>UNIACC</b> MOL · Staff · Seguimiento rematrícula 2027-1</div><div>mperez@uniacc.cl · Ejecutivo</div></div><div class="stamp">DATOS FICTICIOS · PROPUESTA / NO IMPLEMENTADO</div>{body}</body></html>'
  p=f'{H}/{n}.html';open(p,'w').write(html)
  subprocess.run(['google-chrome','--headless=new','--no-sandbox','--disable-gpu','--hide-scrollbars',f'--window-size={w},{h}',f'--screenshot={D}/{n}.png','file://'+p],capture_output=True)
